/// <summary>
/// MPJ_34596_TransferOrderFinalisation, Controller class for transfer shipping list generation service
/// </summary>
class MetTransferOrderShipmentWorkbenchRouteUpdateController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>Constuct new object</summary>
    /// <param name = "_args">Arguments</param>
    /// <param name = "_executionMode">Execution mode</param>
    /// <returns>New Controller Object</returns>
    public static SysOperationController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        SysOperationController controller = new MetTransferOrderShipmentWorkbenchRouteUpdateController();
        controller.parmExecutionMode(_executionMode);
        controller.parmArgs(_args);
        //controller.parmLoadFromSysLastValue(false); 

        return controller;
    }

/// <summary>New object</summary>
protected void new()
{
    super(classstr(MetTransferOrderShipmentWorkbenchRouteUpdateService), methodstr(MetTransferOrderShipmentWorkbenchRouteUpdateService, process), SysOperationExecutionMode::Synchronous);
}

    /// <summary>Main method</summary>
    /// <param name = "_args">Arguments</param>
    public static void main(Args _args)
    {
        METTransferOrderShipmentWorkbenchRouteUpdateContract    dataContract;
        MetTransferOrderShipmentWorkbenchRouteUpdateController  controller;
        FormRun                                     formRun;
        FormDataSource                              inventTransferTable_ds;
        MultiSelectionHelper                        helper;
        InventLocationId                            toWarehouse;
        Map                                         transferMap;
        InventTransferTable                         inventTransferTable;
        METInventTransferTableExt                   metInventTransferTableExt;
        int                                         recordCount = 1;
        container                                   transferOrderShipCon;
        transferMap                            = new Map(Types::String, Types::Container);
        formRun                                = _args.caller();
        inventTransferTable_ds    = formRun.dataSource(formDataSourceStr(MetTransferOrderShipWorkbench, inventTransferTable));
        helper                                 = MultiSelectionHelper::construct();
        helper.parmDataSource(inventTransferTable_ds);

        inventTransferTable       = helper.getfirst();
        select firstonly  metInventTransferTableExt where metInventTransferTableExt.InventTransferTable ==inventTransferTable.RecId;
        toWarehouse = inventTransferTable.InventLocationIdTo;
        while (inventTransferTable)
        {
           
            if(toWarehouse == inventTransferTable.InventLocationIdTo && recordCount > 1 )
            {
                throw Error("@MET:multipleWarehouseError");
            }
            transferOrderShipCon     = conIns(transferOrderShipCon, conLen(transferOrderShipCon) + 1, inventTransferTable.TransferId);
            inventTransferTable   = helper.getNext();
            recordCount++;


        }

        if(conLen(transferOrderShipCon))
        {
            controller              = MetTransferOrderShipmentWorkbenchRouteUpdateController::construct(_args);
            dataContract            = controller.getDataContractObject();
            dataContract.parmTransferOrderList(transferOrderShipCon);
            dataContract.parmPrimaryRoute(metInventTransferTableExt.Route);
            dataContract.parmRouteStop(metInventTransferTableExt.RouteStop);
            controller.startOperation();
        }
        else
        {
            warning("@MET:NoTransferOrderToProcess");
        }
    }

/// <summary>
/// Description
/// </summary>
/// <returns>Generate purchase orders</returns>
public ClassDescription defaultCaption()
{
    return "@MET:UpdateRoutes";
}
